box\": [{\"coord\": [1396, 36, 1423, 63], \"page_id\": 57}], \"content\": \"47\", \"description\": null, \"id\": 1, \"type\": \"page_number\"}, {\"bbox\": [{\"coord\": [624, 101, 880, 123], \"page_id\": 57}], \"content\": \"CAPITAL MOVEMENTS\", \"description\": null, \"id\": 2, \"type\": \"page_header\"}, {\"bbox\": [{\"coord\": [54, 177, 716, 392], \"page_id\": 57}], \"content\": \"Information relating to capital movements between the United States and foreign countries is presented in four sections. Section I contains the principal types of data on capital movements by years from 1935, and currently by months. Each type of data is then broken down into its chief components in the same chronological detail.\", \"description\": null, \"id\": 3, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [54, 426, 714, 607], \"page_id\": 57}], \"content\": \"Section II supplies a geographic breakdown by principal countries for recent months. The total capital movements are given first and then the principal categories are shown separately. In addition, at this point, the total outstanding claims on and liabilities to foreign countries are each presented.\", \"description\": null, \"id\": 4, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [51, 632, 716, 760], \"page_id\": 57}], \"content\": \"Details with respect to capital movements and short-term claims and liabilities are presented in Section III as of the latest month for which the data are available.\", \"description\": null, \"id\": 5, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [109, 791, 717, 820], \"page_id\": 57}], \"content\": \"Section IV contains data for recent months on the\", \"description\": null, \"id\": 6, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [792, 177, 1458, 300], \"page_id\": 57}], \"content\": \"net position in foreign currencies of banks and brokers in the United States, their outstanding foreign exchange contracts, and purchases and sales of foreign exchange, both spot and forward.\", \"description\": null, \"id\": 7, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [792, 329, 1457, 511], \"page_id\": 57}], \"content\": \"These data relating to capital movements are based on reports filed each month by banks, bankers, and brokers throughout the United States. The reports are collected, checked and tabulated by the twelve Federal Reserve Banks. The totals are then forwarded to the Treasury Department for consolidation and publication.\", \"description\": null, \"id\": 8, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [792, 540, 1457, 818], \"page_id\": 57}], \"content\": \"Figures for previous periods may be obtained from the following sources: \\\"Treasury Bulletin\\\", November 1945, for a summary of capital movements, and position in foreign currencies by months, 1942-1945. Supplement to \\\"Treasury Bulletin\\\", November 1945, on \\\"Capital Movements between the United States and Foreign Countries, January 1942 through April 1945\\\", for details during that period. \\\"Treasury Bulletin\\\", March 1942, and earlier issues, for details covering years back to January 2, 1935.\", \"description\": null, \"id\": 9, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [231, 858, 1295, 935], \"page_id\": 57}], \"content\": \"Section I - Historical Summary\\nTable 1.- Net Capital Movement between the United States and Foreign Countries\", \"description\": null, \"id\": 10, \"type\": \"section_header\"}, {\"bbox\": [{\"coord\": [316, 937, 1227, 966], \"page_id\": 57}], \"content\": \"(In thousands of dollars; negative figures indicate a net outflow of capital from the United States)\", \"description\": null, \"id\": 11, \"type\": \"text\"}, {\"bbox\": [{\"coord\": [58, 970, 1458, 1730], \"page_id\": 57}], \"content\": \"<table><tr><th>Calendar year or month</th><th>Net capital movement</th><th>Short-term banking funds</th><th>Brokerage balances</th><th>Transactions in domestic securities</th><th>Transactions in foreign securities</th></tr><tr><td>1935 (Jan. 2, 1935-Jan. 1, 1936)</