_x2 = sum(years[i]**2 for i in range(n))\n\nb = (n * sum_xy - sum_x * sum_y) / (n * sum_x2 - sum_x**2)\na = (sum_y - b * sum_x) / n\n\nprint(f\"\\nOLS Regression equation:\")\nprint(f\"  y = {a:.6f} + {b:.6f} * x\")\n\n# Predict for 1952\nyear_1952 = 1952\nprediction = a + b * year_1952\n\nprint(f\"\\nPrediction for January 1952:\")\nprint(f\"  {prediction:.6f} billions\")\nprint(f\"  Rounded to nearest tenth: {round(prediction, 1)} billions\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
